import re

def get_lincoln_presidency_count():
    try:
        with open('data/session_document.txt', 'r', encoding='utf-8') as f:
            content = f.read()

        # Search for Abraham Lincoln and the number of times he served
        # The document structure suggests looking for patterns like "Abraham Lincoln served as president X times"
        match = re.search(r'Abraham Lincoln served as president (\d+) times', content)
        if match:
            return int(match.group(1))
        else:
            return 'CANNOT_DETERMINE'
    except FileNotFoundError:
        return 'CANNOT_DETERMINE'

print(get_lincoln_presidency_count())
